/// The themes in Settings → Appearance order: (`data-theme` id = the persisted setting, display name, palette).
pub static THEMES: [(&str, &str, &Palette); 7] = [
    ("nocturne", "Nocturne", &NOCTURNE),
    ("matinee", "Matinee", &MATINEE),
    ("graphite", "Graphite", &GRAPHITE),
    ("graphite-light", "Graphite Light", &GRAPHITE_LIGHT),
    ("console", "Console", &CONSOLE),
    ("console-light", "Console Light", &CONSOLE_LIGHT),
    ("console-split", "Console Split", &CONSOLE_SPLIT),
];

/// Each theme's palette inside `.chrome-scope`, indexed like [`THEMES`]; the base palette where nothing differs.
pub static CHROME_PALETTES: [&Palette; 7] = [
    &NOCTURNE,
    &MATINEE,
    &GRAPHITE,
    &GRAPHITE_LIGHT,
    &CONSOLE,
    &CONSOLE_LIGHT,
    &CONSOLE_SPLIT_CHROME,
];

