/// uiStore's `DEFAULT_THEME`.
pub const DEFAULT_THEME_ID: &str = "nocturne";

// Settings → Appearance (uiStore.ts; the density step is AppearanceTab's slider step).
/// Text size: the message body's size in px; every role of the type scale follows it.
pub const TEXT_SIZE_MIN_PX: f32 = 11.0;
pub const TEXT_SIZE_MAX_PX: f32 = 17.0;
pub const TEXT_SIZE_STEP_PX: f32 = 0.5;
pub const DEFAULT_TEXT_SIZE_PX: f32 = 14.5;
/// List density: a multiplier on list-row padding, gaps and avatars.
pub const ROW_SCALE_MIN: f32 = 0.85;
pub const ROW_SCALE_MAX: f32 = 1.3;
pub const ROW_SCALE_STEP: f32 = 0.05;
pub const DEFAULT_ROW_SCALE: f32 = 1.0;

/// The tokens that follow Settings → Appearance (`--ui-text-size-n`, `--ui-row-scale`), from [`scaled`].
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Scaled {
    /// `--ui-text-scale: calc(var(--ui-text-size-n, var(--ui-text-size-default)) / var(--t-fs-body-n))`
    pub ui_text_scale: f32,
    /// `--text-title: calc(var(--t-fs-title) * var(--ui-text-scale))` (px)
    pub text_title: f32,
    /// `--text-body: calc(var(--t-fs-body) * var(--ui-text-scale))` (px)
    pub text_body: f32,
    /// `--text-sender: calc(var(--t-fs-sender) * var(--ui-text-scale))` (px)
    pub text_sender: f32,
    /// `--text-channel: calc(var(--t-fs-channel) * var(--ui-text-scale))` (px)
    pub text_channel: f32,
    /// `--text-member: calc(var(--t-fs-member) * var(--ui-text-scale))` (px)
    pub text_member: f32,
    /// `--text-section: calc(var(--t-fs-section) * var(--ui-text-scale))` (px)
    pub text_section: f32,
    /// `--text-meta: calc(var(--t-fs-meta) * var(--ui-text-scale))` (px)
    pub text_meta: f32,
    /// `--text-reply: calc(var(--t-fs-body) * 0.9 * var(--ui-text-scale))` (px)
    pub text_reply: f32,
    /// `--text-reply--line-height: round(up, calc(var(--t-fs-body) * 0.9 * var(--ui-text-scale) * 1.375), 1px)` (px)
    pub text_reply_line_height: f32,
    /// `--text-micro: calc(var(--t-fs-micro) * var(--ui-text-scale))` (px)
    pub text_micro: f32,
    /// `.list-row { --avatar-scale: var(--ui-row-scale) }`
    pub list_row_avatar_scale: f32,
}

/// The runtime-dependent tokens of `p` at a text size (px, e.g. [`DEFAULT_TEXT_SIZE_PX`]) and a list density
/// (e.g. [`DEFAULT_ROW_SCALE`]): the CSS calc() / round() evaluated in f64 as Chromium does, stored as f32.
pub fn scaled(p: &Palette, text_size_n: f32, row_scale: f32) -> Scaled {
    let text_size_n = text_size_n as f64;
    let row_scale = row_scale as f64;
    let ui_text_scale = text_size_n / (p.t_fs_body_n as f64);
    let text_title = (p.t_fs_title as f64) * ui_text_scale;
    let text_body = (p.t_fs_body as f64) * ui_text_scale;
    let text_sender = (p.t_fs_sender as f64) * ui_text_scale;
    let text_channel = (p.t_fs_channel as f64) * ui_text_scale;
    let text_member = (p.t_fs_member as f64) * ui_text_scale;
    let text_section = (p.t_fs_section as f64) * ui_text_scale;
    let text_meta = (p.t_fs_meta as f64) * ui_text_scale;
    let text_reply = ((p.t_fs_body as f64) * 0.9_f64) * ui_text_scale;
    let text_reply_line_height = crate::css_round(crate::RoundingStrategy::Up, (((p.t_fs_body as f64) * 0.9_f64) * ui_text_scale) * 1.375_f64, 1.0_f64);
    let text_micro = (p.t_fs_micro as f64) * ui_text_scale;
    let list_row_avatar_scale = row_scale;
    Scaled {
        ui_text_scale: ui_text_scale as f32,
        text_title: text_title as f32,
        text_body: text_body as f32,
        text_sender: text_sender as f32,
        text_channel: text_channel as f32,
        text_member: text_member as f32,
        text_section: text_section as f32,
        text_meta: text_meta as f32,
        text_reply: text_reply as f32,
        text_reply_line_height: text_reply_line_height as f32,
        text_micro: text_micro as f32,
        list_row_avatar_scale: list_row_avatar_scale as f32,
    }
}

/// `.image-viewer`: features/chat/ImageViewer.tsx: 'image-viewer chrome-scope' on one element, portaled to the document body.
#[derive(Debug, Clone, PartialEq)]
pub struct ImageViewerScope {
    /// `--viewer-stage`: `var(--color-bg-darkest)`
    pub viewer_stage: Color,
    /// `--viewer-wash`
    pub viewer_wash: f32,
    /// `--viewer-wash-filter`
    pub viewer_wash_filter: &'static [FilterFn],
}

/// `.picture-editor`: components/pictureEditor/PictureEditor.tsx, portaled to the document body.
#[derive(Debug, Clone, PartialEq)]
pub struct PictureEditorScope {
    /// `--crop-veil`: `color-mix(in srgb, var(--color-bg-darkest) 78%, transparent)`
    pub crop_veil: Color,
    /// `--crop-corner`: `color-mix(in srgb, var(--color-bg-darkest) 42%, transparent)`
    pub crop_corner: Color,
    /// `--crop-edge`: `color-mix(in srgb, var(--color-text-primary) 80%, transparent)`
    pub crop_edge: Color,
    /// `--crop-grid`: `color-mix(in srgb, var(--color-text-primary) 30%, transparent)`
    pub crop_grid: Color,
}

/// `.dsel-menu[data-side="above"]`: components/Select.tsx: the menu when it opens above its trigger (below: --dsel-dy unset, the keyframe falls back to -4px).
#[derive(Debug, Clone, PartialEq)]
pub struct DselMenuAboveScope {
    /// `--dsel-dy` (px)
    pub dsel_dy: f32,
}

/// `.theme-preview`: Settings → Appearance theme cards: each card paints its own theme from the --p-* it sets inline (AppearanceTab.tsx THEMES[].preview).
#[derive(Debug, Clone, PartialEq)]
pub struct ThemePreviewScope {
    /// `--color-bg-darkest`: `var(--p-chrome)`
    pub color_bg_darkest: Color,
    /// `--color-bg-dark`: `var(--p-sidebar)`
    pub color_bg_dark: Color,
    /// `--color-bg-mid`: `var(--p-content)`
    pub color_bg_mid: Color,
    /// `--color-bg-light`: `var(--p-raised, var(--p-content))`
    pub color_bg_light: Color,
    /// `--color-accent`: `var(--p-accent)`
    pub color_accent: Color,
    /// `--color-border-divider`: `var(--p-divider)`
    pub color_border_divider: Color,
    /// `--color-text-secondary`: `var(--p-text-secondary)`
    pub color_text_secondary: Color,
    /// `--color-text-muted`: `var(--p-text-muted)`
    pub color_text_muted: Color,
}

